51	namespace aria2 {
52	
53	IteratableChecksumValidator::IteratableChecksumValidator(
54	    const std::shared_ptr<DownloadContext>& dctx,
55	    const std::shared_ptr<PieceStorage>& pieceStorage)
56	    : dctx_(dctx), pieceStorage_(pieceStorage), currentOffset_(0)
57	{
58	}
59	
60	IteratableChecksumValidator::~IteratableChecksumValidator() = default;
61	
62	void IteratableChecksumValidator::validateChunk()
63	{
64	  // Don't guard with !finished() to allow zero-length file to be
65	  // verified.
66	  std::array<unsigned char, 4_k> buf;
67	  size_t length = pieceStorage_->getDiskAdaptor()->readDataDropCache(
68	      buf.data(), buf.size(), currentOffset_);
69	  ctx_->update(buf.data(), length);
70	  currentOffset_ += length;
71	  if (finished()) {
72	    std::string actualDigest = ctx_->digest();
73	    if (dctx_->getDigest() == actualDigest) {
74	      pieceStorage_->markAllPiecesDone();
75	      dctx_->setChecksumVerified(true);
76	    }
77	    else {
78	      A2_LOG_INFO(fmt("Checksum validation failed. expected=%s, actual=%s",
79	                      util::toHex(dctx_->getDigest()).c_str(),
80	                      util::toHex(actualDigest).c_str()));
81	      BitfieldMan bitfield(dctx_->getPieceLength(), dctx_->getTotalLength());
82	      pieceStorage_->setBitfield(bitfield.getBitfield(),
83	                                 bitfield.getBitfieldLength());
84	    }
85	  }
86	}
87	
88	bool IteratableChecksumValidator::finished() const
89	{
90	  if (currentOffset_ >= dctx_->getTotalLength()) {
91	    return true;
92	  }
93	  else {
94	    return false;
95	  }
96	}
97	
98	int64_t IteratableChecksumValidator::getTotalLength() const
99	{
100	  return dctx_->getTotalLength();
101	}
102	
103	void IteratableChecksumValidator::init()
104	{
105	  currentOffset_ = 0;
106	  ctx_ = MessageDigest::create(dctx_->getHashType());
107	}
108	
109	} // namespace aria2
