57	namespace {
58	HashTypeEntry hashTypes[] = {
59	    HashTypeEntry("sha-1", 1),   HashTypeEntry("sha-224", 2),
60	    HashTypeEntry("sha-256", 3), HashTypeEntry("sha-384", 4),
61	    HashTypeEntry("sha-512", 5), HashTypeEntry("md5", 0),
62	    HashTypeEntry("adler32", 0),
63	};
