89	std::vector<std::string> MessageDigest::getSupportedHashTypes()
90	{
91	  std::vector<std::string> rv;
92	  for (const auto& i : hashTypes) {
93	    if (MessageDigestImpl::supports(i.hashType)) {
94	      rv.push_back(i.hashType);
95	    }
96	  }
97	  return rv;
98	}
