100	std::string MessageDigest::getSupportedHashTypeString()
101	{
102	  auto ht = getSupportedHashTypes();
103	  std::stringstream ss;
104	  std::copy(std::begin(ht), std::end(ht),
105	            std::ostream_iterator<std::string>(ss, ", "));
106	  auto res = ss.str();
107	  if (!res.empty()) {
108	    res.erase(ss.str().length() - 2);
109	  }
110	  return res;
