118	bool MessageDigest::isStronger(const std::string& lhs, const std::string& rhs)
119	{
120	  auto lEntry = std::find_if(
121	      std::begin(hashTypes), std::end(hashTypes),
122	      [&lhs](const HashTypeEntry& entry) { return lhs == entry.hashType; });
123	  auto rEntry = std::find_if(
124	      std::begin(hashTypes), std::end(hashTypes),
125	      [&rhs](const HashTypeEntry& entry) { return rhs == entry.hashType; });
126	  if (lEntry == std::end(hashTypes)) {
127	    return false;
128	  }
129	  if (rEntry == std::end(hashTypes)) {
130	    return true;
131	  }
132	  return lEntry->strength > rEntry->strength;
133	}
