135	bool MessageDigest::isValidHash(const std::string& hashType,
136	                                const std::string& hexDigest)
137	{
138	  return util::isHexDigit(hexDigest) && supports(hashType) &&
139	         getDigestLength(hashType) * 2 == hexDigest.size();
140	}
