142	std::string MessageDigest::getCanonicalHashType(const std::string& hashType)
143	{
144	  // This is really backward compatibility for Metalink3.  aria2 only
145	  // supported sha-1, sha-256 and md5 at Metalink3 era.  So we don't
146	  // add alias for sha-224, sha-384 and sha-512.
147	  if ("sha1" == hashType) {
148	    return "sha-1";
149	  }
150	  else if ("sha256" == hashType) {
151	    return "sha-256";
152	  }
153	  else {
154	    return hashType;
155	  }
