57	IteratableChunkChecksumValidator::IteratableChunkChecksumValidator(
58	    const std::shared_ptr<DownloadContext>& dctx,
59	    const std::shared_ptr<PieceStorage>& pieceStorage)
60	    : dctx_(dctx),
61	      pieceStorage_(pieceStorage),
62	      bitfield_(make_unique<BitfieldMan>(dctx_->getPieceLength(),
63	                                         dctx_->getTotalLength())),
64	      currentIndex_(0)
65	{
66	}
67	
68	IteratableChunkChecksumValidator::~IteratableChunkChecksumValidator() = default;
69	
70	void IteratableChunkChecksumValidator::validateChunk()
71	{
72	  if (!finished()) {
73	    std::string actualChecksum;
74	    try {
75	      actualChecksum = calculateActualChecksum();
76	      if (actualChecksum == dctx_->getPieceHashes()[currentIndex_]) {
77	        bitfield_->setBit(currentIndex_);
78	      }
79	      else {
80	        A2_LOG_INFO(
81	            fmt(EX_INVALID_CHUNK_CHECKSUM,
82	                static_cast<unsigned long>(currentIndex_),
83	                static_cast<int64_t>(getCurrentOffset()),
84	                util::toHex(dctx_->getPieceHashes()[currentIndex_]).c_str(),
85	                util::toHex(actualChecksum).c_str()));
86	        bitfield_->unsetBit(currentIndex_);
87	      }
88	    }
89	    catch (RecoverableException& ex) {
90	      A2_LOG_DEBUG_EX(fmt("Caught exception while validating piece index=%lu."
91	                          " Some part of file may be missing."
92	                          " Continue operation.",
93	                          static_cast<unsigned long>(currentIndex_)),
94	                      ex);
95	      bitfield_->unsetBit(currentIndex_);
96	    }
97	
98	    ++currentIndex_;
99	    if (finished()) {
100	      pieceStorage_->setBitfield(bitfield_->getBitfield(),
101	                                 bitfield_->getBitfieldLength());
102	    }
103	  }
104	}
105	
106	std::string IteratableChunkChecksumValidator::calculateActualChecksum()
107	{
108	  int64_t offset = getCurrentOffset();
109	  size_t length;
110	  // When validating last piece
111	  if (currentIndex_ + 1 == dctx_->getNumPieces()) {
112	    length = dctx_->getTotalLength() - offset;
113	  }
114	  else {
115	    length = dctx_->getPieceLength();
116	  }
117	  return digest(offset, length);
118	}
119	
120	void IteratableChunkChecksumValidator::init()
121	{
122	  ctx_ = MessageDigest::create(dctx_->getPieceHashType());
123	  bitfield_->clearAllBit();
124	  currentIndex_ = 0;
125	}
126	
127	std::string IteratableChunkChecksumValidator::digest(int64_t offset,
128	                                                     size_t length)
129	{
130	  std::array<unsigned char, 4_k> buf;
131	  ctx_->reset();
132	  int64_t max = offset + length;
133	  while (offset < max) {
134	    size_t r = pieceStorage_->getDiskAdaptor()->readDataDropCache(
135	        buf.data(), std::min(static_cast<int64_t>(buf.size()), max - offset),
136	        offset);
137	    if (r == 0) {
138	      throw DL_ABORT_EX(
139	          fmt(EX_FILE_READ, dctx_->getBasePath().c_str(), "data is too short"));
140	    }
141	    ctx_->update(buf.data(), r);
142	    offset += r;
143	  }
144	  return ctx_->digest();
145	}
146	
147	bool IteratableChunkChecksumValidator::finished() const
148	{
149	  if (currentIndex_ >= dctx_->getNumPieces()) {
150	    return true;
151	  }
152	  else {
153	    return false;
154	  }
155	}
156	
157	int64_t IteratableChunkChecksumValidator::getCurrentOffset() const
158	{
159	  return static_cast<int64_t>(currentIndex_) * dctx_->getPieceLength();
160	}
161	
162	int64_t IteratableChunkChecksumValidator::getTotalLength() const
163	{
164	  return dctx_->getTotalLength();
165	}
