52	std::string digest(MessageDigest* ctx, const std::shared_ptr<BinaryStream>& bs,
53	                   int64_t offset, int64_t length)
54	{
55	  std::array<unsigned char, 4_k> buf;
56	  lldiv_t res = lldiv(length, buf.size());
57	  int64_t iteration = res.quot;
58	  size_t tail = res.rem;
59	  for (int64_t i = 0; i < iteration; ++i) {
60	    ssize_t readLength = bs->readData(buf.data(), buf.size(), offset);
61	    if ((size_t)readLength != buf.size()) {
62	      throw DL_ABORT_EX(fmt(EX_FILE_READ, "n/a", "data is too short"));
63	    }
64	    ctx->update(buf.data(), readLength);
65	    offset += readLength;
66	  }
67	  if (tail) {
68	    ssize_t readLength = bs->readData(buf.data(), tail, offset);
69	    if ((size_t)readLength != tail) {
70	      throw DL_ABORT_EX(fmt(EX_FILE_READ, "n/a", "data is too short"));
71	    }
72	    ctx->update(buf.data(), readLength);
73	  }
74	  return ctx->digest();
75	}
76	
77	void digest(unsigned char* md, size_t mdLength, MessageDigest* ctx,
78	            const void* data, size_t length)
79	{
80	  size_t reqLength = ctx->getDigestLength();
81	  if (mdLength < reqLength) {
82	    throw DL_ABORT_EX(fmt("Insufficient space for storing message digest:"
83	                          " %lu required, but only %lu is allocated",
84	                          static_cast<unsigned long>(reqLength),
85	                          static_cast<unsigned long>(mdLength)));
86	  }
87	  ctx->update(data, length);
88	  ctx->digest(md);
89	}
