51	class MessageDigestImpl {
52	public:
53	  typedef std::function<std::unique_ptr<MessageDigestImpl>()> factory_t;
54	  typedef std::tuple<factory_t, size_t> hash_info_t;
55	  typedef std::map<std::string, hash_info_t> hashes_t;
56	
57	  template <typename T> inline static hash_info_t make_hi()
58	  {
59	    return std::make_tuple([]() { return make_unique<T>(); }, T::length());
60	  }
61	
62	private:
63	  static hashes_t hashes;
64	
65	  MessageDigestImpl(const MessageDigestImpl&) = delete;
66	  MessageDigestImpl& operator=(const MessageDigestImpl&) = delete;
67	
68	public:
69	  virtual ~MessageDigestImpl() = default;
70	  static std::unique_ptr<MessageDigestImpl> sha1();
71	
72	  inline static std::unique_ptr<MessageDigestImpl>
73	  create(const std::string& hashType)
74	  {
75	    auto i = hashes.find(hashType);
76	    if (i == hashes.end()) {
77	      return nullptr;
78	    }
79	    return std::get<0>(i->second)();
80	  }
81	
82	  inline static bool supports(const std::string& hashType)
83	  {
84	    auto i = hashes.find(hashType);
85	    return i != hashes.end();
86	  }
87	
88	  inline static size_t getDigestLength(const std::string& hashType)
89	  {
90	    auto i = hashes.find(hashType);
91	    if (i == hashes.end()) {
92	      return 0;
93	    }
94	    return std::get<1>(i->second);
95	  }
96	
97	public:
98	  virtual size_t getDigestLength() const = 0;
99	  virtual void reset() = 0;
100	  virtual void update(const void* data, size_t length) = 0;
101	  virtual void digest(unsigned char* md) = 0;
102	
103	protected:
104	  MessageDigestImpl() = default;
105	};
