#endif
#ifdef HAVE_EVP_SHA224
    {"sha-512", make_hi<MessageDigestBase<EVP_sha512>>()},
#endif
    {"md5", make_hi<MessageDigestMD5>()},
    ADLER32_MESSAGE_DIGEST};

} // namespace aria2

