63	template <const EVP_MD* (*init_fn)()>
64	class MessageDigestBase : public MessageDigestImpl {
65	public:
66	  MessageDigestBase()
67	      : ctx_(EVP_MD_CTX_new()), md_(init_fn()), len_(EVP_MD_size(md_))
68	  {
69	    EVP_MD_CTX_reset(ctx_);
70	    reset();
71	  }
72	  virtual ~MessageDigestBase() { EVP_MD_CTX_free(ctx_); }
73	
74	  static size_t length() { return EVP_MD_size(init_fn()); }
75	  virtual size_t getDigestLength() const CXX11_OVERRIDE { return len_; }
76	  virtual void reset() CXX11_OVERRIDE { EVP_DigestInit_ex(ctx_, md_, nullptr); }
77	  virtual void update(const void* data, size_t length) CXX11_OVERRIDE
78	  {
79	    auto bytes = reinterpret_cast<const char*>(data);
80	    while (length) {
81	      size_t l = std::min(length, (size_t)std::numeric_limits<uint32_t>::max());
82	      EVP_DigestUpdate(ctx_, bytes, l);
83	      length -= l;
84	      bytes += l;
85	    }
86	  }
87	  virtual void digest(unsigned char* md) CXX11_OVERRIDE
88	  {
89	    unsigned int len;
90	    EVP_DigestFinal_ex(ctx_, md, &len);
91	  }
92	
93	private:
94	  EVP_MD_CTX* ctx_;
95	  const EVP_MD* md_;
96	  const size_t len_;
97	};
